import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"写屏障与卡表","description":"","frontmatter":{"title":"写屏障与卡表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-barrier-card-table.md","filePath":"cs/write-barrier-card-table.md","lastUpdated":1789023840000}'),h={name:"cs/write-barrier-card-table.md"};function _(u,a,m,b,f,C){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="写屏障与卡表" tabindex="-1">写屏障与卡表 <a class="header-anchor" href="#写屏障与卡表" aria-label="Permalink to &quot;写屏障与卡表&quot;">​</a></h1><div class="epigraph"><p>分代或增量 GC 不能每次扫描全堆。写屏障在指针写入时记录「脏」：老→幼的引用进记忆集，卡表用一字节标记一页有写。</p><footer>—— 据 Ungar, Generation Scavenging；Wilson and Moher；Jones 手册；HotSpot 卡表实践整理</footer></div><p>上一课<a href="/cs/refcounting-gc">引用计数</a> 在赋值处做事。追踪式分代也在赋值处做事，但目的不同：<strong>记住跨代指针</strong>。缺口是写屏障与卡表。并发 GC 下一课还要用屏障维持三色。主干分代课已给「幼代多死」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只扫幼代：必须知道老年代谁指向幼代，否则漏标。记忆集：精确到对象或到卡（512B）。写屏障：<code>*p=q</code> 时若 p 老 q 幼则标脏。缺口是<strong>这笔商店税</strong>，不是 RC 循环。</p><p>JIT 必须在每条指针 store 插屏障（可优化消除显然的同代）。</p><h3 id="卡表不是-cpu-cache" tabindex="-1">卡表不是 CPU cache <a class="header-anchor" href="#卡表不是-cpu-cache" aria-label="Permalink to &quot;卡表不是 CPU cache&quot;">​</a></h3><p>card table 是 GC 数据结构。不要和 cache line 混，尽管大小常按页/卡对齐。</p><p><span class="marginnote">Ungar 1984。HotSpot 卡表。Jones 手册分代章。本课不写全部 SATB/G1 细节，并发课再接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每卡一字节。store 置脏。幼代 GC：扫脏卡找跨代指针当根。清理脏位。</p>',11)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E6%8C%87%E9%92%88%20store%22%5D%20--%3E%20WB%5B%22%E5%86%99%E5%B1%8F%E9%9A%9C%22%5D%0A%20%20WB%20--%3E%20CARD%5B%22%E8%84%8F%E5%8D%A1%22%5D%0A%20%20CARD%20--%3E%20YGC%5B%22%E5%B9%BC%E4%BB%A3%E6%89%AB%E6%8F%8F%E9%A2%9D%E5%A4%96%E6%A0%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/cs/alias-analysis">别名</a>：屏障消除需证明 store 不创跨代——难，常保守插。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>假共享：多线程写邻接卡。字节卡有意减小。不要漏屏障：漏则漏回收或悬空，比多一次屏障更糟。</p><p>读屏障：复制式移动时读要跟随转发，或 Brooks 屏障。点名，并发课用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整并发算法。后课默认：分代靠写屏障+记忆集。下一课并发与增量 GC。</p><p>也不把屏障当 CPU 内存屏障的全部（有重叠：store 顺序），内存模型后课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写屏障记录对 GC 重要的指针写。</li><li>卡表近似记忆集，幼代扫脏卡。</li><li>JIT 必须生成屏障；漏则不正确。</li><li>出处：Ungar；Jones 手册；HotSpot 卡表。</li></ul>',9))])}const E=i(h,[["render",_]]);export{B as __pageData,E as default};
